// Returns the captured home configuration for an asset type, or a minimal default for the rest.
static const char* GetToolboxHomeConfig(const std::string& assetType) {
    if (assetType == "Model")     return g_toolbox_home_config_Model;
    if (assetType == "Audio")     return g_toolbox_home_config_Audio;
    if (assetType == "Decal")     return g_toolbox_home_config_Decal;
    if (assetType == "Video")     return g_toolbox_home_config_Video;
    if (assetType == "Plugin")    return g_toolbox_home_config_Plugin;
    if (assetType == "Animation") return g_toolbox_home_config_Animation;
    return g_toolbox_home_config_default;
}
